package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException;
import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal; import bo.edu.uagrm.saludu.shared.persistence.*; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/medical/patients") public class MedicalPatientHistoryController { private final JdbcTemplate j; private final DatabaseActorContext c; private final ObjectMapper m; public MedicalPatientHistoryController(JdbcTemplate j,DatabaseActorContext c,ObjectMapper m){this.j=j;this.c=c;this.m=m;} @GetMapping("/{id}") @PreAuthorize("hasAnyRole('REVIEW_DOCTOR','SPECIALIST')") @Transactional(readOnly=true) public LegacyAvailabilityResponse<Object> get(@PathVariable UUID id,@AuthenticationPrincipal SessionPrincipal p){c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));try{String value=j.queryForObject("select salud_u.obtener_historia_longitudinal_area(?)::text",String.class,id);return LegacyAvailabilityResponse.success(m.readValue(value,Object.class));}catch(org.springframework.dao.DataAccessException e){throw new AvailabilityException(404,"No tienes acceso clínico a este paciente.");}catch(Exception e){throw new AvailabilityException(400,"No se pudo consultar la historia clínica.");}}}
